-- READ-ONLY verification of the read posture and scope drift of supabase_read_only_user. Generated by tools/intelligence/ro_scope.py. Expected value is on each row.
with permitted(name) as (values ('alert_sources'), ('alerts'), ('alerts_tz_backfill_backup_20261106'), ('backup_aemo_after_now_20261123'), ('backup_aemo_published_at_20261123'), ('backup_rss_published_at_20261124'), ('backup_source_registry_retire_20261123'), ('backup_twilio_published_at_20261123'), ('brief_lessons_learned'), ('captains_daily_briefs'), ('content_signals'), ('domain_heartbeat_latest'), ('domain_heartbeats'), ('domain_heartbeats_latest'), ('domain_registry'), ('downdetector_baseline_history'), ('downdetector_learned_thresholds'), ('emergency_alert_feed_state'), ('emergency_alert_source_integrity'), ('emergency_alert_summary_state'), ('external_fetch_usage'), ('intelligence_briefs'), ('intelligence_event_validation'), ('intelligence_events'), ('intelligence_ingestion_quality_daily'), ('intelligence_source_health'), ('intelligence_source_health_latest'), ('intelligence_source_registry'), ('llm_call_metrics'), ('llm_daily_costs'), ('llm_usage_by_model_30d'), ('llm_usage_daily_totals_14d'), ('ori_sector_activity'), ('ori_source_documents'), ('ori_theme_frequency'), ('ori_watch_items'), ('signal_corroboration'), ('signal_escalation_history'), ('source_registry_by_tier'), ('source_reliability_snapshot'), ('system_heartbeat'), ('validation_job_runs'), ('watchlist_items'), ('watchlist_tracking')),
col_limited(name) as (values ('captains_daily_briefs'), ('llm_call_metrics')),
public_rels as (select c.oid, c.relname from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('r','v','m','p'))
select 'member_of_pg_read_all_data (platform-managed; table scope is application-level)' as check, pg_has_role('supabase_read_only_user', 'pg_read_all_data', 'member')::text as value, 'true (cannot be revoked by postgres); if false the scope is now database-enforced' as expected
union all
select 'member_of_pg_monitor (other sessions query text readable; the guard refuses those functions and views)', pg_has_role('supabase_read_only_user', 'pg_monitor', 'member')::text, 'true today' 
union all
select 'default_transaction_read_only', coalesce((select array_to_string(s.setconfig, ';') from pg_db_role_setting s where s.setrole = 'supabase_read_only_user'::regrole), '(none)'), 'default_transaction_read_only=on'
union all
select 'public_relation_names', string_agg(r.relname, ',' order by r.relname), 'run: python tools/intelligence/ro_scope.py drift "<this value>" ; must print NEW: (none)'
from public_rels r
union all
select 'relations_with_effective_write_privileges', coalesce(string_agg(n.nspname || '.' || c.relname, ', ' order by c.relname), '(none)'), '(none)'
from pg_class c join pg_namespace n on n.oid = c.relnamespace
where c.relkind in ('r','v','m','p','f') and n.nspname not in ('pg_catalog','information_schema','pg_toast')
  and (has_table_privilege('supabase_read_only_user', c.oid, 'INSERT,UPDATE,DELETE,TRUNCATE') or has_any_column_privilege('supabase_read_only_user', c.oid, 'INSERT,UPDATE'))
union all
select 'schemas_it_can_create_in', count(*)::text, '0'
from pg_namespace n where has_schema_privilege('supabase_read_only_user', n.oid, 'create') and n.nspname not like 'pg_%' and n.nspname <> 'information_schema'
union all
-- a SECURITY DEFINER function it can execute would run with its owner's rights and could read or write outside this scope
select 'secdef_functions_executable_non_system', coalesce(string_agg(n.nspname || '.' || p.proname, ', '), '(none)'), '(none)'
from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where p.prosecdef and n.nspname not in ('pg_catalog','information_schema') and has_function_privilege('supabase_read_only_user', p.oid, 'execute')
union all
-- a view runs with its OWNER's privileges: every permitted view must depend only on permitted relations
select 'permitted_views_depending_on_unpermitted_relations',
  coalesce(string_agg(distinct v.relname || ' -> ' || d.relname, ', '), '(none)'), '(none)'
from pg_class v join permitted p on p.name = v.relname and v.relnamespace = 'public'::regnamespace and v.relkind in ('v','m')
join pg_rewrite rw on rw.ev_class = v.oid
join pg_depend dep on dep.objid = rw.oid and dep.classid = 'pg_rewrite'::regclass and dep.refclassid = 'pg_class'::regclass
join pg_class d on d.oid = dep.refobjid and d.relnamespace = 'public'::regnamespace and d.oid <> v.oid
where d.relname not in (select name from permitted);
